<!doctype html><html lang="ur" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $booking->reference }} — ٹیلرنگ جاب شیٹ</title><style>@page{size:A4;margin:11mm}*{box-sizing:border-box}body{font-family:"Noto Nastaliq Urdu","Segoe UI",sans-serif;color:#17212b;margin:0}.sheet{max-width:190mm;margin:auto;border:1px solid #293b4c;padding:10mm}.head{display:flex;justify-content:space-between;gap:20px;border-bottom:2px solid #293b4c;padding-bottom:10px}.ltr{direction:ltr;text-align:left}.ref{font:bold 18px monospace}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:12px}.field{border:1px solid #ccd4dc;padding:8px;min-height:48px}.field strong{display:block;font-size:12px;color:#52616f}.wide{grid-column:1/-1}table{width:100%;border-collapse:collapse;margin-top:14px}th,td{border:1px solid #8796a3;padding:7px;text-align:right}.signatures{display:grid;grid-template-columns:1fr 1fr;gap:45px;margin-top:45px}.signature{border-top:1px solid #333;padding-top:5px;text-align:center}.actions{text-align:center;margin:0 0 12px}.actions button{padding:9px 18px}@media print{.actions{display:none}.sheet{border:0;padding:0}}</style></head><body><div class="actions"><button onclick="window.print()">پرنٹ کریں</button></div><section class="sheet"><header class="head"><div><h1 style="margin:0">{{ $storefront->display_name }}</h1><div>{{ $storefront->public_phone }}</div><div>{{ collect(preg_split('/\s*،\s*/u', $storefront->address ?: $storefront->city))->filter()->unique()->join('، ') }}</div></div><div class="ltr"><div>TAILORING JOB SHEET</div><div class="ref">{{ $booking->reference }}</div><div>{{ $booking->confirmed_at?->format('d-m-Y h:i A') }}</div></div></header><div class="grid"><div class="field"><strong>گاہک</strong>{{ $booking->customer_name }}</div><div class="field"><strong>فون</strong><span class="ltr">{{ $booking->phone }}</span></div><div class="field"><strong>خدمت</strong>{{ $booking->service?->name }}</div><div class="field"><strong>تعداد</strong>{{ $booking->suit_quantity }}</div><div class="field"><strong>پیمائش کا طریقہ</strong>{{ \App\Models\StorefrontTailoringService::measurementMethodLabels()[$booking->measurement_method] ?? $booking->measurement_method }}</div><div class="field"><strong>تیاری کی تاریخ</strong>{{ $booking->promised_date?->format('d-m-Y') }}</div><div class="field"><strong>حتمی قیمت</strong>Rs {{ number_format((float)$booking->final_price,2) }}</div><div class="field"><strong>پیشگی وصولی</strong>Rs {{ number_format((float)$booking->payment_claimed_amount,2) }}</div><div class="field wide"><strong>تفصیل / دکان کا نوٹ</strong>{{ collect([$booking->message,$booking->admin_notes])->filter()->join(' — ') ?: '—' }}</div></div><h2 style="font-size:17px">محفوظ پیمائش</h2><table><thead><tr><th>پیمائش</th><th>قدر</th><th>اکائی</th></tr></thead><tbody>@forelse($booking->order->measurementValues as $value)<tr><td>{{ $value->label }}</td><td>{{ $value->value }}</td><td>{{ $value->unit }}</td></tr>@empty<tr><td colspan="3">اس وقت محفوظ پیمائش موجود نہیں؛ منتخب طریقے کے مطابق پیمائش مکمل کریں۔</td></tr>@endforelse</tbody></table><div class="signatures"><div class="signature">گاہک / وصول کنندہ</div><div class="signature">دکان / کاریگر</div></div></section></body></html>
